// Bistro Sync - Transform & Normalize
// Handles single submission OR an array of submissions on $input.all()

function toTitleCase(str) {
  if (!str || typeof str !== 'string') return '';
  return str
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
}

function formatTime12h(timeStr) {
  if (!timeStr || typeof timeStr !== 'string') return '';
  const parts = timeStr.split(':');
  if (parts.length < 2) return timeStr;
  let h = parseInt(parts[0], 10);
  const m = parseInt(parts[1], 10);
  if (isNaN(h) || isNaN(m)) return timeStr;
  const period = h >= 12 ? 'PM' : 'AM';
  h = h % 12;
  if (h === 0) h = 12;
  const mm = m.toString().padStart(2, '0');
  return `${h}:${mm} ${period}`;
}

function hasAllergyFlag(restriction) {
  if (!restriction || typeof restriction !== 'string') return false;
  const r = restriction.toLowerCase();
  if (r === 'none' || r === 'n/a' || r === 'null') return false;
  return /allergy|celiac|anaphylactic/i.test(restriction);
}

const out = [];

for (const item of $input.all()) {
  // Webhook may put parsed body under .body, or fields may be at top level.
  const src = item.json.body && typeof item.json.body === 'object'
    ? item.json.body
    : item.json;

  const rawGuest = src['Guest Name'] || src.guestName || src.guest_name || '';
  const rawDate = src['Reservation Date'] || src.reservationDate || src.reservation_date || '';
  const rawTime = src['Time'] || src.time || '';
  const rawParty = src['Party Size'] || src.partySize || src.party_size || 0;
  const rawTable = src['Table Number'] || src.tableNumber || src.table_number || '';
  const rawDiet = src['Dietary Restrictions'] || src.dietaryRestrictions || src.dietary_restrictions || '';
  const rawServer = src['Server Name'] || src.serverName || src.server_name || '';

  const guestName = toTitleCase(String(rawGuest).trim());
  const formattedTime = formatTime12h(String(rawTime).trim());
  const dietary = String(rawDiet || '').trim();
  const isAllergy = hasAllergyFlag(dietary);

  out.push({
    json: {
      'Guest Name': guestName,
      'Reservation Date': String(rawDate).trim(),
      'Time': formattedTime,
      'Time Raw': String(rawTime).trim(),
      'Party Size': Number(rawParty) || 0,
      'Table Number': String(rawTable).trim(),
      'Dietary Restrictions': dietary || 'None',
      'Server Name': toTitleCase(String(rawServer).trim()),
      'Allergy Alert': isAllergy,
      'Upsert Key': `${guestName}|${String(rawDate).trim()}|${String(rawTable).trim()}`
    }
  });
}

return out;

